new file mode 100644
index 0000000..261f331
--- /dev/null
+++ b/.claude/hooks/dist/agent-ledger.mjs
@@ -0,0 +1,13 @@
+// Hook: record agent lifecycle metadata to .prometheus/agent-ledger.jsonl.
+// Registered for SubagentStart, SubagentStop, PostToolUseFailure,
+// TaskCompleted and UserPromptSubmit. Never blocks; never records content.
+import { allow, runHook } from "./lib/hook-io.mjs";
+import { appendEntry, entryFromHook, readKbdPosition } from "./lib/ledger.mjs";
+import { projectDir } from "./lib/paths.mjs";
+await runHook("agent-ledger", (input) => {
+    const root = projectDir();
+    const entry = entryFromHook(input, new Date(), readKbdPosition(root));
+    if (entry !== null)
+        appendEntry(root, entry);
+    return allow();
+});
diff --git a/.claude/hooks/dist/karpathy-boundary.mjs b/.claude/hooks/dist/karpathy-boundary.mjs
new file mode 100644
index 0000000..2b58295
--- /dev/null
+++ b/.claude/hooks/dist/karpathy-boundary.mjs
@@ -0,0 +1,105 @@
+// KBD hook bridge: record a successful task/change/phase boundary with the
+// machine-level Karpathy progress recorder, from Node, on any OS.
+//
+//   node .claude/hooks/dist/karpathy-boundary.mjs --boundary task|change|phase [--project-root <dir>]
+//
+// Invoked by .kbd-orchestrator/hooks-config.json (augment entries). The KBD
+// dispatcher supplies KBD_HOOK_* in the environment; they pass straight through
+// to the recorder. Every outcome — including a missing recorder or Python — is
+// appended to the agent ledger, and the process always exits 0.
+import { spawnSync } from "node:child_process";
+import { existsSync } from "node:fs";
+import os from "node:os";
+import path from "node:path";
+import { fileURLToPath } from "node:url";
+import { appendEntry, makeEntry, readKbdPosition, sanitizeId } from "./lib/ledger.mjs";
+import { projectDir } from "./lib/paths.mjs";
+const BOUNDARIES = new Set(["task", "change", "phase"]);
+const PROBE_TIMEOUT_MS = 2_000;
+const RECORD_TIMEOUT_MS = 12_000;
+function argValue(argv, flag) {
+    const i = argv.indexOf(flag);
+    return i >= 0 ? argv[i + 1] : undefined;
+}
+/** First existing recorder path, in the documented resolution order. */
+export function resolveRecorder(env, home = os.homedir()) {
+    const candidates = [];
+    const explicit = env["KARPATHY_RECORDER"];
+    if (explicit !== undefined && explicit !== "")
+        candidates.push(explicit);
+    const kbdRoot = env["KBD_ORCHESTRATOR_ROOT"];
+    if (kbdRoot !== undefined && kbdRoot !== "") {
+        candidates.push(path.join(kbdRoot, "..", "karpathy-progress-memory", "scripts", "record-progress.py"));
+    }
+    candidates.push(path.join(home, ".claude", "skills", "karpathy-progress-memory", "scripts", "record-progress.py"));
+    return candidates.find((c) => existsSync(c));
+}
+/** First Python 3 interpreter that answers `--version`: python3, python, py -3. */
+export function resolveInterpreter(env) {
+    const candidates = [
+        { command: "python3", prefix: [] },
+        { command: "python", prefix: [] },
+        { command: "py", prefix: ["-3"] },
+    ];
+    for (const candidate of candidates) {
+        const probe = spawnSync(candidate.command, [...candidate.prefix, "--version"], {
+            encoding: "utf8",
+            timeout: PROBE_TIMEOUT_MS,
+            windowsHide: true,
+            env,
+        });
+        if (probe.status === 0 && /Python 3\./.test(`${probe.stdout}${probe.stderr}`))
+            return candidate;
+    }
+    return undefined;
+}
+/** Extract the recorder's `status` from its JSON stdout (last JSON object line). */
+export function recorderStatus(stdout) {
+    const lines = stdout.trim().split("\n").reverse();
+    for (const line of lines) {
+        try {
+            const value = JSON.parse(line);
+            if (typeof value.status === "string")
+                return sanitizeId(value.status);
+        }
+        catch {
+            // not JSON; keep looking
+        }
+    }
+    return undefined;
+}
+export function main(argv, env) {
+    const boundary = argValue(argv, "--boundary") ?? "";
+    const root = argValue(argv, "--project-root") ?? projectDir(env);
+    const kbd = readKbdPosition(root);
+    const log = (event, outcome) => {
+        appendEntry(root, makeEntry({ ts: new Date().toISOString(), event, outcome, kbd_phase: kbd.phase, kbd_change: kbd.change }));
+        return `${event}:${outcome}`;
+    };
+    if (!BOUNDARIES.has(boundary))
+        return log("boundary_degraded", "bad-boundary-arg");
+    const recorder = resolveRecorder(env);
+    if (recorder === undefined)
+        return log("boundary_degraded", `${boundary}:no-recorder`);
+    const python = resolveInterpreter(env);
+    if (python === undefined)
+        return log("boundary_degraded", `${boundary}:no-python`);
+    const run = spawnSync(python.command, [...python.prefix, recorder, "--project-root", root, "--from-hook", "--boundary", boundary], { cwd: root, encoding: "utf8", timeout: RECORD_TIMEOUT_MS, windowsHide: true, env });
+    if (run.error !== undefined) {
+        const code = run.error.code ?? "error";
+        return log("boundary_degraded", `${boundary}:${code === "ETIMEDOUT" ? "timeout" : "spawn-failed"}`);
+    }
+    if (run.status !== 0)
+        return log("boundary_degraded", `${boundary}:recorder-exit-${run.status ?? "signal"}`);
+    return log("boundary_recorded", `${boundary}:${recorderStatus(run.stdout) ?? "unknown"}`);
+}
+// Run only when executed directly (tests import the helpers).
+if (process.argv[1] !== undefined && path.resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
+    try {
+        process.stderr.write(`karpathy-boundary: ${main(process.argv.slice(2), process.env)}\n`);
+    }
+    catch (err) {
+        process.stderr.write(`karpathy-boundary: warning: ${err instanceof Error ? err.message : String(err)}\n`);
+    }
+    process.exitCode = 0;
+}
diff --git a/.claude/hooks/dist/karpathy-flush.mjs b/.claude/hooks/dist/karpathy-flush.mjs
new file mode 100644
index 0000000..65cc1f6
--- /dev/null
+++ b/.claude/hooks/dist/karpathy-flush.mjs
@@ -0,0 +1,18 @@
+// Hook: at Stop, SessionEnd and PreCompact, summarize new ledger lines into a
+// scanned session note and queue it for the project knowledge base (a detached
+// drainer runs `pk ingest`, which is too slow to block on).
+// Always exits 0; problems surface as a user-visible warning.
+import { allow, runHook, warn } from "./lib/hook-io.mjs";
+import { flush } from "./lib/flush.mjs";
+import { projectDir } from "./lib/paths.mjs";
+await runHook("karpathy-flush", () => {
+    const result = flush(projectDir());
+    switch (result.status) {
+        case "blocked":
+            return warn(`karpathy-flush: session note withheld — PHI/secret scan found ${result.matches} match(es); nothing was written to .prometheus/raw/`);
+        case "queued":
+            return warn(`karpathy-flush: ${result.reason}; session note queued in .prometheus/outbox/`);
+        default:
+            return allow();
+    }
+});
diff --git a/.claude/hooks/dist/lib/flush.mjs b/.claude/hooks/dist/lib/flush.mjs
new file mode 100644
index 0000000..5a65e0e
--- /dev/null
+++ b/.claude/hooks/dist/lib/flush.mjs
@@ -0,0 +1,154 @@
+// Karpathy flush: condense new ledger lines into a session note, scan it, and
+// queue it for the project knowledge base. Pure helpers are exported for tests;
+// `flush()` performs the filesystem work and starts the background drainer.
+import { closeSync, existsSync, mkdirSync, openSync, readFileSync, renameSync, rmSync, statSync, writeFileSync, } from "node:fs";
+import path from "node:path";
+import { appendEntry, ledgerPath, makeEntry, parseLedger } from "./ledger.mjs";
+import { drainOutbox, outboxDir, startDetachedDrain } from "./pk.mjs";
+import { parseAllowlist, scanText } from "./scan.mjs";
+const LOCK_STALE_MS = 60_000;
+function prometheusDir(root) {
+    return path.join(root, ".prometheus");
+}
+function readCursor(root) {
+    try {
+        const value = JSON.parse(readFileSync(path.join(prometheusDir(root), ".flush-cursor"), "utf8"));
+        return typeof value.offset === "number" && value.offset >= 0 ? value.offset : 0;
+    }
+    catch {
+        return 0;
+    }
+}
+function writeCursor(root, offset) {
+    writeFileSync(path.join(prometheusDir(root), ".flush-cursor"), `${JSON.stringify({ offset })}\n`);
+}
+/** Read ledger bytes appended since the cursor; resets when the ledger was rotated. */
+export function readDelta(root) {
+    const file = ledgerPath(root);
+    if (!existsSync(file))
+        return { entries: [], end: 0 };
+    const buf = readFileSync(file);
+    let start = readCursor(root);
+    if (start > buf.length)
+        start = 0;
+    // Only consume whole lines so a concurrent partial append is left for next time.
+    const lastNewline = buf.lastIndexOf(0x0a);
+    const end = lastNewline < start ? start : lastNewline + 1;
+    return { entries: parseLedger(buf.subarray(start, end).toString("utf8")), end };
+}
+function count(items, key) {
+    const out = new Map();
+    for (const item of items) {
+        const k = key(item);
+        if (k !== undefined)
+            out.set(k, (out.get(k) ?? 0) + 1);
+    }
+    return out;
+}
+/** Render a metadata-only markdown summary of ledger entries. */
+export function renderNote(entries) {
+    const first = entries[0]?.ts ?? "";
+    const last = entries[entries.length - 1]?.ts ?? "";
+    const sessions = [...count(entries, (e) => e.session_id).keys()];
+    const phases = [...count(entries, (e) => e.kbd_phase).keys()];
+    const changes = [...count(entries, (e) => e.kbd_change).keys()];
+    const agents = new Map();
+    for (const e of entries) {
+        const agent = e.agent_type ?? "(main session)";
+        const row = agents.get(agent) ?? new Map();
+        row.set(e.event, (row.get(e.event) ?? 0) + 1);
+        agents.set(agent, row);
+    }
+    const events = [...count(entries, (e) => e.event).entries()].sort();
+    const failedTools = [...count(entries.filter((e) => e.event === "PostToolUseFailure"), (e) => e.tool_name).entries()].sort();
+    const lines = [
+        `# Agent activity ${first.slice(0, 10)}`,
+        "",
+        `- Window: \`${first}\` → \`${last}\``,
+        `- Sessions: ${sessions.length > 0 ? sessions.map((s) => `\`${s}\``).join(", ") : "none recorded"}`,
+        `- KBD phase: ${phases.map((p) => `\`${p}\``).join(", ") || "none"}; changes: ${changes.map((c) => `\`${c}\``).join(", ") || "none"}`,
+        `- Ledger lines summarized: ${entries.length}`,
+        "",
+        "## Events",
+        "",
+        ...events.map(([event, n]) => `- \`${event}\`: ${n}`),
+        "",
+        "## Agents",
+        "",
+        "| Agent | Started | Stopped | Tool failures | Tasks completed |",
+        "|---|---|---|---|---|",
+        ...[...agents.entries()].sort(([a], [b]) => a.localeCompare(b)).map(([agent, row]) => `| \`${agent}\` | ${row.get("SubagentStart") ?? 0} | ${row.get("SubagentStop") ?? 0} | ${row.get("PostToolUseFailure") ?? 0} | ${row.get("TaskCompleted") ?? 0} |`),
+    ];
+    if (failedTools.length > 0) {
+        lines.push("", "## Failing tools", "", ...failedTools.map(([tool, n]) => `- \`${tool}\`: ${n}`));
+    }
+    const degraded = entries.filter((e) => e.event === "boundary_degraded" || e.event === "flush_blocked").length;
+    if (degraded > 0)
+        lines.push("", `> Karpathy loop health: ${degraded} degraded or blocked record(s) — see the ledger.`);
+    return `${lines.join("\n")}\n`;
+}
+function acquireLock(root) {
+    const lock = path.join(prometheusDir(root), ".flush.lock");
+    try {
+        if (existsSync(lock) && Date.now() - statSync(lock).mtimeMs > LOCK_STALE_MS)
+            rmSync(lock, { force: true });
+        closeSync(openSync(lock, "wx"));
+        return () => rmSync(lock, { force: true });
+    }
+    catch {
+        return null;
+    }
+}
+function compactTs(iso) {
+    return iso.replace(/[-:]/g, "").replace(/\.\d+Z$/, "Z");
+}
+export function flush(root, now = new Date(), env = process.env) {
+    const dir = prometheusDir(root);
+    mkdirSync(dir, { recursive: true });
+    const release = acquireLock(root);
+    if (release === null)
+        return { status: "locked" };
+    try {
+        const { entries, end } = readDelta(root);
+        if (entries.length === 0) {
+            writeCursor(root, end);
+            return { status: "empty" };
+        }
+        const text = renderNote(entries);
+        const allowFile = path.join(dir, "scan-allowlist.json");
+        const matches = scanText(text, parseAllowlist(existsSync(allowFile) ? readFileSync(allowFile, "utf8") : undefined));
+        if (matches.length > 0) {
+            // Deliberately skip a blocked delta: retrying it would block every later
+            // flush. The flush_blocked line records that (and how many) were withheld.
+            writeCursor(root, end);
+            appendEntry(root, makeEntry({ ts: now.toISOString(), event: "flush_blocked", outcome: `blocked:${matches.length}` }));
+            return { status: "blocked", matches: matches.length };
+        }
+        const name = `${compactTs(now.toISOString())}-agent-activity.md`;
+        const rawDir = path.join(dir, "raw");
+        mkdirSync(rawDir, { recursive: true });
+        const tmp = path.join(rawDir, `.${name}.tmp`);
+        const note = path.join(rawDir, name);
+        writeFileSync(tmp, text);
+        renameSync(tmp, note);
+        const outbox = outboxDir(root);
+        mkdirSync(outbox, { recursive: true });
+        writeFileSync(path.join(outbox, name), text);
+        // Advance only once the note is durable in raw/ and queued in outbox/, so a
+        // failed write leaves the delta to be summarized by the next flush.
+        writeCursor(root, end);
+        // KARPATHY_FLUSH_SYNC=1 drains inline (tests, CI); otherwise a detached
+        // drainer delivers the outbox so the Stop hook never waits on `pk`.
+        if (env["KARPATHY_FLUSH_SYNC"] !== "1") {
+            startDetachedDrain(root, env);
+            return { status: "queued-async", note };
+        }
+        const report = drainOutbox(root, env);
+        return report.lastError === undefined
+            ? { status: "ingested", note }
+            : { status: "queued", note, reason: report.lastError };
+    }
+    finally {
+        release();
+    }
+}
diff --git a/.claude/hooks/dist/lib/hook-io.mjs b/.claude/hooks/dist/lib/hook-io.mjs
new file mode 100644
index 0000000..3a98e51
--- /dev/null
+++ b/.claude/hooks/dist/lib/hook-io.mjs
@@ -0,0 +1,94 @@
+// Shared input/output contract for every project hook.
+//
+// A hook is a pure `handler(input) => HookResult`. `runHook` owns the process
+// boundary: it reads one JSON object from stdin, calls the handler, writes the
+// Claude Code hook output, and sets the exit code. Malformed input never blocks
+// work — it produces a single warning and exit 0.
+export const allow = () => ({ kind: "allow" });
+export const deny = (reason) => ({ kind: "deny", reason });
+export const feedback = (text) => ({ kind: "feedback", text });
+export const context = (text) => ({ kind: "context", text });
+export const warn = (message) => ({ kind: "warn", message });
+/** Parse raw stdin. Returns null for empty, non-JSON, or non-object input. */
+export function parseInput(raw) {
+    const trimmed = raw.trim();
+    if (trimmed === "")
+        return null;
+    try {
+        const value = JSON.parse(trimmed);
+        if (value === null || typeof value !== "object" || Array.isArray(value))
+            return null;
+        return value;
+    }
+    catch {
+        return null;
+    }
+}
+/** Map a handler result onto the Claude Code hook output contract. */
+export function renderResult(result, eventName) {
+    switch (result.kind) {
+        case "allow":
+            return { stdout: "", stderr: "", exitCode: 0 };
+        case "deny":
+            if (eventName === "PreToolUse") {
+                const body = {
+                    hookSpecificOutput: {
+                        hookEventName: "PreToolUse",
+                        permissionDecision: "deny",
+                        permissionDecisionReason: result.reason,
+                    },
+                };
+                return { stdout: JSON.stringify(body), stderr: "", exitCode: 0 };
+            }
+            // Events without a permission decision block via exit 2 + stderr reason.
+            return { stdout: "", stderr: `${result.reason}\n`, exitCode: 2 };
+        case "feedback":
+        case "context": {
+            const body = {
+                hookSpecificOutput: { hookEventName: eventName, additionalContext: result.text },
+            };
+            return { stdout: JSON.stringify(body), stderr: "", exitCode: 0 };
+        }
+        case "warn":
+            return {
+                stdout: JSON.stringify({ systemMessage: result.message }),
+                stderr: "",
+                exitCode: 0,
+            };
+    }
+}
+async function readStdin() {
+    if (process.stdin.isTTY)
+        return "";
+    const chunks = [];
+    for await (const chunk of process.stdin) {
+        chunks.push(typeof chunk === "string" ? Buffer.from(chunk) : chunk);
+    }
+    return Buffer.concat(chunks).toString("utf8");
+}
+/**
+ * Process entry point for a hook. Any thrown error is reported as a warning
+ * and exits 0: a broken hook must never stop an agent from working.
+ */
+export async function runHook(name, handler) {
+    let output;
+    try {
+        const input = parseInput(await readStdin());
+        if (input === null) {
+            output = { stdout: "", stderr: `[${name}] warning: ignoring malformed hook input\n`, exitCode: 0 };
+        }
+        else {
+            const result = await handler(input);
+            output = renderResult(result, input.hook_event_name ?? "");
+        }
+    }
+    catch (err) {
+        const message = err instanceof Error ? err.message : String(err);
+        output = { stdout: "", stderr: `[${name}] warning: hook failed: ${message}\n`, exitCode: 0 };
+    }
+    if (output.stdout !== "")
+        process.stdout.write(output.stdout);
+    if (output.stderr !== "")
+        process.stderr.write(output.stderr);
+    process.exitCode = output.exitCode;
+}
diff --git a/.claude/hooks/dist/lib/ledger.mjs b/.claude/hooks/dist/lib/ledger.mjs
new file mode 100644
index 0000000..942cf43
--- /dev/null
+++ b/.claude/hooks/dist/lib/ledger.mjs
@@ -0,0 +1,139 @@
+// Metadata-only agent ledger (.prometheus/agent-ledger.jsonl).
+//
+// `.prometheus/` is committed to git, so this module is the privacy boundary:
+// every line is built from a fixed allowlist of fields whose values are either
+// enumerated by this code or sanitized identifiers. Tool inputs, tool outputs,
+// prompt text and file contents can never reach the ledger — a new field in a
+// hook payload is ignored by construction, not by remembering to strip it.
+import { createHash } from "node:crypto";
+import { appendFileSync, mkdirSync, readFileSync } from "node:fs";
+import path from "node:path";
+import { scanText } from "./scan.mjs";
+export const LEDGER_FIELDS = [
+    "ts",
+    "session_id",
+    "agent_type",
+    "agent_id",
+    "event",
+    "tool_name",
+    "outcome",
+    "kbd_phase",
+    "kbd_change",
+    "prompt_chars",
+    "prompt_sha256",
+];
+/** Hook events recorded by the agent-ledger hook, and the outcome each implies. */
+const EVENT_OUTCOMES = {
+    SubagentStart: "started",
+    SubagentStop: "stopped",
+    PostToolUseFailure: "failed",
+    TaskCompleted: "completed",
+    UserPromptSubmit: "submitted",
+};
+export const RECORDED_EVENTS = Object.keys(EVENT_OUTCOMES);
+const MAX_ID = 128;
+/**
+ * Keep only identifier-shaped values (agent names like `plugin:reviewer`, UUIDs,
+ * tool names such as `mcp__server__tool`, KBD ids). Anything else is dropped
+ * rather than escaped. The charset excludes `@`, `/` and `+` so emails, URLs
+ * and DSNs cannot pass, and every value is also run through the PHI/secret
+ * scanner, so identifier-shaped PHI (e.g. an SSN) is dropped too.
+ */
+export function sanitizeId(value) {
+    if (typeof value !== "string")
+        return undefined;
+    const trimmed = value.trim();
+    if (trimmed === "" || trimmed.length > MAX_ID)
+        return undefined;
+    if (!/^[A-Za-z0-9._:-]+$/.test(trimmed))
+        return undefined;
+    return scanText(trimmed).length === 0 ? trimmed : undefined;
+}
+/** Current KBD phase/change from the runtime waypoint; empty when absent. */
+export function readKbdPosition(projectRoot) {
+    try {
+        const raw = readFileSync(path.join(projectRoot, ".kbd-orchestrator", "current-waypoint.json"), "utf8");
+        const wp = JSON.parse(raw);
+        const phase = sanitizeId(wp["phase"]);
+        const change = sanitizeId(wp["nextChange"]) ?? sanitizeId(wp["change"]);
+        return { ...(phase !== undefined ? { phase } : {}), ...(change !== undefined ? { change } : {}) };
+    }
+    catch {
+        return {};
+    }
+}
+export function sha256(text) {
+    return createHash("sha256").update(text, "utf8").digest("hex");
+}
+/** Assemble an entry from explicit parts, dropping undefined and non-allowlisted keys. */
+export function makeEntry(parts) {
+    const entry = {};
+    for (const field of LEDGER_FIELDS) {
+        const value = parts[field];
+        if (value !== undefined)
+            entry[field] = value;
+    }
+    if (typeof entry["ts"] !== "string" || typeof entry["event"] !== "string") {
+        throw new Error("ledger entry requires ts and event");
+    }
+    return entry;
+}
+/**
+ * Build the ledger entry for a Claude Code hook payload, or null when the
+ * event is not one the ledger records.
+ */
+export function entryFromHook(input, now, kbd) {
+    const event = sanitizeId(input.hook_event_name);
+    if (event === undefined)
+        return null;
+    const outcome = EVENT_OUTCOMES[event];
+    if (outcome === undefined)
+        return null;
+    const prompt = event === "UserPromptSubmit" && typeof input["prompt"] === "string" ? input["prompt"] : undefined;
+    return makeEntry({
+        ts: now.toISOString(),
+        event,
+        outcome,
+        session_id: sanitizeId(input.session_id),
+        agent_type: sanitizeId(input.agent_type),
+        agent_id: sanitizeId(input.agent_id),
+        tool_name: event === "PostToolUseFailure" ? sanitizeId(input.tool_name) : undefined,
+        kbd_phase: kbd.phase,
+        kbd_change: kbd.change,
+        prompt_chars: prompt?.length,
+        prompt_sha256: prompt === undefined ? undefined : sha256(prompt),
+    });
+}
+export function ledgerPath(projectRoot) {
+    return path.join(projectRoot, ".prometheus", "agent-ledger.jsonl");
+}
+/**
+ * Append one line. Lines are kept well under 4 KB so a single O_APPEND write
+ * stays line-atomic when hooks run concurrently.
+ */
+export function appendEntry(projectRoot, entry) {
+    const line = `${JSON.stringify(entry)}\n`;
+    if (Buffer.byteLength(line) > 4000)
+        throw new Error("ledger line exceeds 4000 bytes");
+    const file = ledgerPath(projectRoot);
+    mkdirSync(path.dirname(file), { recursive: true });
+    appendFileSync(file, line, { encoding: "utf8" });
+}
+/** Parse ledger text, skipping blank or corrupt lines. */
+export function parseLedger(text) {
+    const out = [];
+    for (const line of text.split("\n")) {
+        if (line.trim() === "")
+            continue;
+        try {
+            const value = JSON.parse(line);
+            if (value !== null && typeof value === "object" && typeof value.event === "string") {
+                out.push(value);
+            }
+        }
+        catch {
+            // A torn or hand-edited line is skipped, never fatal.
+        }
+    }
+    return out;
+}
