new file mode 100644
index 0000000..9357dd1
--- /dev/null
+++ b/.claude/hooks/dist/lib/paths.mjs
@@ -0,0 +1,61 @@
+// Project-path helpers that behave the same on POSIX and Windows.
+//
+// All comparisons happen on POSIX-style strings so that a Windows path such as
+// `C:\repo\internal\x.go` and its POSIX form resolve identically, regardless of
+// which OS the hook is running on.
+const WINDOWS_DRIVE = /^[A-Za-z]:[\\/]/;
+/** Replace backslashes with forward slashes and collapse duplicate slashes. */
+export function toPosix(p) {
+    return p.replace(/\\/g, "/").replace(/\/{2,}/g, "/");
+}
+function isAbsolute(p) {
+    return p.startsWith("/") || WINDOWS_DRIVE.test(p);
+}
+/**
+ * Normalize `.` and `..` segments of a POSIX-style path. Returns null when a
+ * relative path climbs above its starting point (e.g. `../x`).
+ */
+function normalizeSegmentsOrNull(p) {
+    const prefix = p.startsWith("/") ? "/" : "";
+    const out = [];
+    for (const segment of p.split("/")) {
+        if (segment === "" || segment === ".")
+            continue;
+        if (segment === "..") {
+            if (out.length === 0 && prefix === "")
+                return null;
+            out.pop();
+            continue;
+        }
+        out.push(segment);
+    }
+    return prefix + out.join("/");
+}
+function normalizeSegments(p) {
+    return normalizeSegmentsOrNull(p) ?? p;
+}
+/** Lower-case a leading drive letter so `C:/x` and `c:/x` compare equal. */
+function foldDrive(p) {
+    return WINDOWS_DRIVE.test(p) ? p[0].toLowerCase() + p.slice(1) : p;
+}
+/** Project root: CLAUDE_PROJECT_DIR when set, otherwise the working directory. */
+export function projectDir(env = process.env, cwd = process.cwd()) {
+    const fromEnv = env["CLAUDE_PROJECT_DIR"];
+    return normalizeSegments(toPosix(fromEnv !== undefined && fromEnv !== "" ? fromEnv : cwd));
+}
+/**
+ * Path of `target` relative to `root`, POSIX-style, without a leading `./`.
+ * Returns null when `target` lies outside `root`.
+ */
+export function rel(root, target) {
+    const base = foldDrive(normalizeSegments(toPosix(root))).replace(/\/$/, "");
+    const posixTarget = toPosix(target);
+    if (!isAbsolute(posixTarget)) {
+        const relative = normalizeSegmentsOrNull(posixTarget);
+        return relative === null || relative === "" ? null : relative;
+    }
+    const full = foldDrive(normalizeSegments(posixTarget));
+    if (full === base)
+        return "";
+    return full.startsWith(`${base}/`) ? full.slice(base.length + 1) : null;
+}
diff --git a/.claude/hooks/dist/lib/pk.mjs b/.claude/hooks/dist/lib/pk.mjs
new file mode 100644
index 0000000..f2b0cd3
--- /dev/null
+++ b/.claude/hooks/dist/lib/pk.mjs
@@ -0,0 +1,72 @@
+// Delivery of session notes to the project knowledge base via the `pk` CLI.
+//
+// `pk ingest` compiles notes with an LLM and routinely takes 10+ seconds, far
+// longer than a Stop hook should block. Notes are therefore queued in
+// .prometheus/outbox/ and drained by a detached background process; an entry is
+// deleted only after `pk` accepts it, so a failure is retried on the next flush.
+import { spawn, spawnSync } from "node:child_process";
+import { existsSync, readdirSync, rmSync } from "node:fs";
+import path from "node:path";
+import { fileURLToPath } from "node:url";
+export const PK_DRAIN_TIMEOUT_MS = 120_000;
+/** Resolve how to run `pk`: PK_BIN (a binary, or a .mjs/.cjs/.js script run with node) or `pk` on PATH. */
+export function pkCommand(env) {
+    const bin = env["PK_BIN"];
+    if (bin !== undefined && bin !== "") {
+        return /\.(mjs|cjs|js)$/.test(bin) ? { command: process.execPath, prefix: [bin] } : { command: bin, prefix: [] };
+    }
+    return { command: "pk", prefix: [] };
+}
+export function ingest(root, note, env, timeoutMs = PK_DRAIN_TIMEOUT_MS) {
+    const { command, prefix } = pkCommand(env);
+    const r = spawnSync(command, [...prefix, "ingest", "--scope", "project", "--source", "claude-hooks", note], {
+        cwd: root,
+        encoding: "utf8",
+        timeout: timeoutMs,
+        windowsHide: true,
+        env,
+    });
+    if (r.error !== undefined) {
+        const code = r.error.code;
+        return { ok: false, reason: code === "ETIMEDOUT" ? "pk timed out" : code === "ENOENT" ? "pk not found" : `pk failed: ${code ?? "error"}` };
+    }
+    return r.status === 0 ? { ok: true } : { ok: false, reason: `pk exited ${r.status ?? "by signal"}` };
+}
+export function outboxDir(root) {
+    return path.join(root, ".prometheus", "outbox");
+}
+/** Ingest every queued note, oldest first; delete each one `pk` accepts. */
+export function drainOutbox(root, env) {
+    const dir = outboxDir(root);
+    if (!existsSync(dir))
+        return { delivered: 0, remaining: 0 };
+    const notes = readdirSync(dir).filter((f) => f.endsWith(".md")).sort();
+    let delivered = 0;
+    let lastError;
+    for (const name of notes) {
+        const file = path.join(dir, name);
+        const result = ingest(root, file, env);
+        if (result.ok) {
+            rmSync(file, { force: true });
+            delivered += 1;
+        }
+        else {
+            lastError = result.reason;
+            if (result.reason === "pk not found")
+                break; // no point retrying the rest now
+        }
+    }
+    const report = { delivered, remaining: notes.length - delivered };
+    return lastError === undefined ? report : { ...report, lastError };
+}
+/** Start the background drainer and return immediately. */
+export function startDetachedDrain(root, env) {
+    const drainer = path.join(path.dirname(fileURLToPath(import.meta.url)), "..", "pk-drain.mjs");
+    const child = spawn(process.execPath, [drainer, root], {
+        detached: true,
+        stdio: "ignore",
+        windowsHide: true,
+        env,
+    });
+    child.unref();
+}
diff --git a/.claude/hooks/dist/lib/scan.mjs b/.claude/hooks/dist/lib/scan.mjs
new file mode 100644
index 0000000..b0b9638
--- /dev/null
+++ b/.claude/hooks/dist/lib/scan.mjs
@@ -0,0 +1,49 @@
+// PHI / secret scanner for content that will be committed under .prometheus/.
+//
+// Reports pattern ids and positions only — never the matched text — so a scan
+// report can itself be logged or shown without leaking what it found.
+export const RULES = [
+    { id: "us-ssn", pattern: /\b(?!000|666|9\d\d)\d{3}-(?!00)\d{2}-(?!0000)\d{4}\b/g },
+    { id: "mrn", pattern: /\bMRN\s*[:#=]?\s*[A-Z0-9][A-Z0-9-]{4,}\b/gi },
+    { id: "email", pattern: /\b[A-Za-z0-9._%+-]+@[A-Za-z0-9-]+(?:\.[A-Za-z0-9-]+)*\.[A-Za-z]{2,}\b/g },
+    { id: "phone", pattern: /(?<![\w-])(?:\+?1[-.\s])?\(?\d{3}\)?[-.\s]\d{3}[-.\s]\d{4}(?![\w-])/g },
+    { id: "bearer-token", pattern: /\bBearer\s+[A-Za-z0-9._~+/-]{20,}=*/g },
+    { id: "sk-key", pattern: /\bsk-[A-Za-z0-9_-]{16,}/g },
+    { id: "aws-access-key", pattern: /\bAKIA[0-9A-Z]{16}\b/g },
+    { id: "private-key", pattern: /-----BEGIN [A-Z ]*PRIVATE KEY-----/g },
+    { id: "credentialed-dsn", pattern: /\b[a-z][a-z0-9+.-]*:\/\/[^\s:@/]+:[^\s@/]+@/gi },
+];
+function allowed(matched, allowlist) {
+    return (allowlist.literals ?? []).some((literal) => literal !== "" && matched.includes(literal));
+}
+/** Scan text and return every match position (never the matched text). */
+export function scanText(text, allowlist = {}) {
+    const matches = [];
+    const lines = text.split(/\r?\n/);
+    lines.forEach((line, index) => {
+        for (const rule of RULES) {
+            rule.pattern.lastIndex = 0;
+            for (const m of line.matchAll(rule.pattern)) {
+                if (allowed(m[0], allowlist))
+                    continue;
+                matches.push({ rule: rule.id, line: index + 1, column: (m.index ?? 0) + 1 });
+            }
+        }
+    });
+    return matches;
+}
+/** Parse `.prometheus/scan-allowlist.json` content; invalid content means no allowlist. */
+export function parseAllowlist(raw) {
+    if (raw === undefined)
+        return {};
+    try {
+        const value = JSON.parse(raw);
+        const literals = Array.isArray(value.literals)
+            ? value.literals.filter((x) => typeof x === "string")
+            : [];
+        return { literals };
+    }
+    catch {
+        return {};
+    }
+}
diff --git a/.claude/hooks/dist/pk-drain.mjs b/.claude/hooks/dist/pk-drain.mjs
new file mode 100644
index 0000000..8434b9c
--- /dev/null
+++ b/.claude/hooks/dist/pk-drain.mjs
@@ -0,0 +1,22 @@
+// Background drainer: deliver queued session notes in .prometheus/outbox/ to
+// the project knowledge base. Started detached by karpathy-flush; also safe to
+// run by hand: `node .claude/hooks/dist/pk-drain.mjs [<project-root>]`.
+import { drainOutbox } from "./lib/pk.mjs";
+import { appendEntry, makeEntry } from "./lib/ledger.mjs";
+import { projectDir } from "./lib/paths.mjs";
+const root = process.argv[2] ?? projectDir();
+try {
+    const report = drainOutbox(root, process.env);
+    if (report.delivered > 0 || report.lastError !== undefined) {
+        appendEntry(root, makeEntry({
+            ts: new Date().toISOString(),
+            event: report.lastError === undefined ? "kb_ingested" : "kb_deferred",
+            outcome: `delivered:${report.delivered},remaining:${report.remaining}`,
+        }));
+    }
+    process.stdout.write(`pk-drain: delivered ${report.delivered}, remaining ${report.remaining}${report.lastError ? ` (${report.lastError})` : ""}\n`);
+}
+catch (err) {
+    process.stderr.write(`pk-drain: warning: ${err instanceof Error ? err.message : String(err)}\n`);
+}
+process.exitCode = 0;
diff --git a/.claude/hooks/dist/scan-prometheus.mjs b/.claude/hooks/dist/scan-prometheus.mjs
new file mode 100644
index 0000000..1ad6d0f
--- /dev/null
+++ b/.claude/hooks/dist/scan-prometheus.mjs
@@ -0,0 +1,59 @@
+// CLI: scan every text file under .prometheus/ (or the directory given as the
+// first argument) for PHI and secrets. Exits 1 when anything matches, printing
+// file:line:column and the rule id — never the matched text.
+import { existsSync, readdirSync, readFileSync, statSync } from "node:fs";
+import path from "node:path";
+import { fileURLToPath } from "node:url";
+import { parseAllowlist, scanText } from "./lib/scan.mjs";
+const MAX_BYTES = 5 * 1024 * 1024;
+function walk(dir, out) {
+    for (const entry of readdirSync(dir, { withFileTypes: true })) {
+        const full = path.join(dir, entry.name);
+        if (entry.isDirectory())
+            walk(full, out);
+        else if (entry.isFile())
+            out.push(full);
+    }
+}
+function looksBinary(buf) {
+    return buf.subarray(0, 8000).includes(0);
+}
+// npm runs scripts from .claude/hooks/, so default to the repository that
+// contains this script (dist/ -> hooks/ -> .claude/ -> repo) unless Claude
+// Code supplied CLAUDE_PROJECT_DIR or a directory was passed explicitly.
+const repoRoot = process.env["CLAUDE_PROJECT_DIR"] ?? path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..", "..", "..");
+const root = process.argv[2] ?? path.join(repoRoot, ".prometheus");
+if (!existsSync(root)) {
+    console.log(`scan-prometheus: ${root} does not exist; nothing to scan`);
+    process.exit(0);
+}
+const allowlistFile = path.join(root, "scan-allowlist.json");
+const allowlist = parseAllowlist(existsSync(allowlistFile) ? readFileSync(allowlistFile, "utf8") : undefined);
+const files = [];
+walk(root, files);
+let hits = 0;
+let scanned = 0;
+for (const file of files.sort()) {
+    if (path.resolve(file) === path.resolve(allowlistFile))
+        continue;
+    if (statSync(file).size > MAX_BYTES) {
+        console.error(`scan-prometheus: ${path.relative(root, file)}: skipped (over 5 MB) — review manually`);
+        hits += 1;
+        continue;
+    }
+    const buf = readFileSync(file);
+    if (looksBinary(buf))
+        continue;
+    scanned += 1;
+    for (const m of scanText(buf.toString("utf8"), allowlist)) {
+        hits += 1;
+        console.error(`scan-prometheus: ${path.relative(root, file).split(path.sep).join("/")}:${m.line}:${m.column}: ${m.rule}`);
+    }
+}
+if (hits > 0) {
+    console.error(`scan-prometheus: ${hits} finding(s) in ${scanned} file(s); remove the content or add a reviewed literal to scan-allowlist.json`);
+    process.exitCode = 1;
+}
+else {
+    console.log(`scan-prometheus: clean (${scanned} file(s) scanned)`);
+}
