@@ -0,0 +1,66 @@
+// Project-path helpers that behave the same on POSIX and Windows.
+//
+// All comparisons happen on POSIX-style strings so that a Windows path such as
+// `C:\repo\internal\x.go` and its POSIX form resolve identically, regardless of
+// which OS the hook is running on.
+
+const WINDOWS_DRIVE = /^[A-Za-z]:[\\/]/;
+
+/** Replace backslashes with forward slashes and collapse duplicate slashes. */
+export function toPosix(p: string): string {
+  return p.replace(/\\/g, "/").replace(/\/{2,}/g, "/");
+}
+
+function isAbsolute(p: string): boolean {
+  return p.startsWith("/") || WINDOWS_DRIVE.test(p);
+}
+
+/**
+ * Normalize `.` and `..` segments of a POSIX-style path. Returns null when a
+ * relative path climbs above its starting point (e.g. `../x`).
+ */
+function normalizeSegmentsOrNull(p: string): string | null {
+  const prefix = p.startsWith("/") ? "/" : "";
+  const out: string[] = [];
+  for (const segment of p.split("/")) {
+    if (segment === "" || segment === ".") continue;
+    if (segment === "..") {
+      if (out.length === 0 && prefix === "") return null;
+      out.pop();
+      continue;
+    }
+    out.push(segment);
+  }
+  return prefix + out.join("/");
+}
+
+function normalizeSegments(p: string): string {
+  return normalizeSegmentsOrNull(p) ?? p;
+}
+
+/** Lower-case a leading drive letter so `C:/x` and `c:/x` compare equal. */
+function foldDrive(p: string): string {
+  return WINDOWS_DRIVE.test(p) ? p[0]!.toLowerCase() + p.slice(1) : p;
+}
+
+/** Project root: CLAUDE_PROJECT_DIR when set, otherwise the working directory. */
+export function projectDir(env: NodeJS.ProcessEnv = process.env, cwd: string = process.cwd()): string {
+  const fromEnv = env["CLAUDE_PROJECT_DIR"];
+  return normalizeSegments(toPosix(fromEnv !== undefined && fromEnv !== "" ? fromEnv : cwd));
+}
+
+/**
+ * Path of `target` relative to `root`, POSIX-style, without a leading `./`.
+ * Returns null when `target` lies outside `root`.
+ */
+export function rel(root: string, target: string): string | null {
+  const base = foldDrive(normalizeSegments(toPosix(root))).replace(/\/$/, "");
+  const posixTarget = toPosix(target);
+  if (!isAbsolute(posixTarget)) {
+    const relative = normalizeSegmentsOrNull(posixTarget);
+    return relative === null || relative === "" ? null : relative;
+  }
+  const full = foldDrive(normalizeSegments(posixTarget));
+  if (full === base) return "";
+  return full.startsWith(`${base}/`) ? full.slice(base.length + 1) : null;
+}
diff --git a/.claude/hooks/src/lib/pk.mts b/.claude/hooks/src/lib/pk.mts
new file mode 100644
index 0000000..19e4059
--- /dev/null
+++ b/.claude/hooks/src/lib/pk.mts
@@ -0,0 +1,83 @@
+// Delivery of session notes to the project knowledge base via the `pk` CLI.
+//
+// `pk ingest` compiles notes with an LLM and routinely takes 10+ seconds, far
+// longer than a Stop hook should block. Notes are therefore queued in
+// .prometheus/outbox/ and drained by a detached background process; an entry is
+// deleted only after `pk` accepts it, so a failure is retried on the next flush.
+import { spawn, spawnSync } from "node:child_process";
+import { existsSync, readdirSync, rmSync } from "node:fs";
+import path from "node:path";
+import { fileURLToPath } from "node:url";
+
+export const PK_DRAIN_TIMEOUT_MS = 120_000;
+
+/** Resolve how to run `pk`: PK_BIN (a binary, or a .mjs/.cjs/.js script run with node) or `pk` on PATH. */
+export function pkCommand(env: NodeJS.ProcessEnv): { command: string; prefix: string[] } {
+  const bin = env["PK_BIN"];
+  if (bin !== undefined && bin !== "") {
+    return /\.(mjs|cjs|js)$/.test(bin) ? { command: process.execPath, prefix: [bin] } : { command: bin, prefix: [] };
+  }
+  return { command: "pk", prefix: [] };
+}
+
+export type IngestResult = { readonly ok: true } | { readonly ok: false; readonly reason: string };
+
+export function ingest(root: string, note: string, env: NodeJS.ProcessEnv, timeoutMs: number = PK_DRAIN_TIMEOUT_MS): IngestResult {
+  const { command, prefix } = pkCommand(env);
+  const r = spawnSync(command, [...prefix, "ingest", "--scope", "project", "--source", "claude-hooks", note], {
+    cwd: root,
+    encoding: "utf8",
+    timeout: timeoutMs,
+    windowsHide: true,
+    env,
+  });
+  if (r.error !== undefined) {
+    const code = (r.error as NodeJS.ErrnoException).code;
+    return { ok: false, reason: code === "ETIMEDOUT" ? "pk timed out" : code === "ENOENT" ? "pk not found" : `pk failed: ${code ?? "error"}` };
+  }
+  return r.status === 0 ? { ok: true } : { ok: false, reason: `pk exited ${r.status ?? "by signal"}` };
+}
+
+export function outboxDir(root: string): string {
+  return path.join(root, ".prometheus", "outbox");
+}
+
+export interface DrainReport {
+  readonly delivered: number;
+  readonly remaining: number;
+  readonly lastError?: string;
+}
+
+/** Ingest every queued note, oldest first; delete each one `pk` accepts. */
+export function drainOutbox(root: string, env: NodeJS.ProcessEnv): DrainReport {
+  const dir = outboxDir(root);
+  if (!existsSync(dir)) return { delivered: 0, remaining: 0 };
+  const notes = readdirSync(dir).filter((f) => f.endsWith(".md")).sort();
+  let delivered = 0;
+  let lastError: string | undefined;
+  for (const name of notes) {
+    const file = path.join(dir, name);
+    const result = ingest(root, file, env);
+    if (result.ok) {
+      rmSync(file, { force: true });
+      delivered += 1;
+    } else {
+      lastError = result.reason;
+      if (result.reason === "pk not found") break; // no point retrying the rest now
+    }
+  }
+  const report: DrainReport = { delivered, remaining: notes.length - delivered };
+  return lastError === undefined ? report : { ...report, lastError };
+}
+
+/** Start the background drainer and return immediately. */
+export function startDetachedDrain(root: string, env: NodeJS.ProcessEnv): void {
+  const drainer = path.join(path.dirname(fileURLToPath(import.meta.url)), "..", "pk-drain.mjs");
+  const child = spawn(process.execPath, [drainer, root], {
+    detached: true,
+    stdio: "ignore",
+    windowsHide: true,
+    env,
+  });
+  child.unref();
+}
diff --git a/.claude/hooks/src/lib/scan.mts b/.claude/hooks/src/lib/scan.mts
new file mode 100644
index 0000000..25db761
--- /dev/null
+++ b/.claude/hooks/src/lib/scan.mts
@@ -0,0 +1,66 @@
+// PHI / secret scanner for content that will be committed under .prometheus/.
+//
+// Reports pattern ids and positions only — never the matched text — so a scan
+// report can itself be logged or shown without leaking what it found.
+
+export interface ScanRule {
+  readonly id: string;
+  readonly pattern: RegExp;
+}
+
+export interface ScanMatch {
+  readonly rule: string;
+  readonly line: number;
+  readonly column: number;
+}
+
+export interface Allowlist {
+  /** Exact substrings that are known-synthetic (e.g. `noreply@anthropic.com`). */
+  readonly literals?: readonly string[];
+}
+
+export const RULES: readonly ScanRule[] = [
+  { id: "us-ssn", pattern: /\b(?!000|666|9\d\d)\d{3}-(?!00)\d{2}-(?!0000)\d{4}\b/g },
+  { id: "mrn", pattern: /\bMRN\s*[:#=]?\s*[A-Z0-9][A-Z0-9-]{4,}\b/gi },
+  { id: "email", pattern: /\b[A-Za-z0-9._%+-]+@[A-Za-z0-9-]+(?:\.[A-Za-z0-9-]+)*\.[A-Za-z]{2,}\b/g },
+  { id: "phone", pattern: /(?<![\w-])(?:\+?1[-.\s])?\(?\d{3}\)?[-.\s]\d{3}[-.\s]\d{4}(?![\w-])/g },
+  { id: "bearer-token", pattern: /\bBearer\s+[A-Za-z0-9._~+/-]{20,}=*/g },
+  { id: "sk-key", pattern: /\bsk-[A-Za-z0-9_-]{16,}/g },
+  { id: "aws-access-key", pattern: /\bAKIA[0-9A-Z]{16}\b/g },
+  { id: "private-key", pattern: /-----BEGIN [A-Z ]*PRIVATE KEY-----/g },
+  { id: "credentialed-dsn", pattern: /\b[a-z][a-z0-9+.-]*:\/\/[^\s:@/]+:[^\s@/]+@/gi },
+];
+
+function allowed(matched: string, allowlist: Allowlist): boolean {
+  return (allowlist.literals ?? []).some((literal) => literal !== "" && matched.includes(literal));
+}
+
+/** Scan text and return every match position (never the matched text). */
+export function scanText(text: string, allowlist: Allowlist = {}): ScanMatch[] {
+  const matches: ScanMatch[] = [];
+  const lines = text.split(/\r?\n/);
+  lines.forEach((line, index) => {
+    for (const rule of RULES) {
+      rule.pattern.lastIndex = 0;
+      for (const m of line.matchAll(rule.pattern)) {
+        if (allowed(m[0], allowlist)) continue;
+        matches.push({ rule: rule.id, line: index + 1, column: (m.index ?? 0) + 1 });
+      }
+    }
+  });
+  return matches;
+}
+
+/** Parse `.prometheus/scan-allowlist.json` content; invalid content means no allowlist. */
+export function parseAllowlist(raw: string | undefined): Allowlist {
+  if (raw === undefined) return {};
+  try {
+    const value = JSON.parse(raw) as { literals?: unknown };
+    const literals = Array.isArray(value.literals)
+      ? value.literals.filter((x): x is string => typeof x === "string")
+      : [];
+    return { literals };
+  } catch {
+    return {};
+  }
+}
