index 0000000..b25dfe3
--- /dev/null
+++ b/.claude/hooks/src/pk-drain.mts
@@ -0,0 +1,25 @@
+// Background drainer: deliver queued session notes in .prometheus/outbox/ to
+// the project knowledge base. Started detached by karpathy-flush; also safe to
+// run by hand: `node .claude/hooks/dist/pk-drain.mjs [<project-root>]`.
+import { drainOutbox } from "./lib/pk.mjs";
+import { appendEntry, makeEntry } from "./lib/ledger.mjs";
+import { projectDir } from "./lib/paths.mjs";
+
+const root = process.argv[2] ?? projectDir();
+try {
+  const report = drainOutbox(root, process.env);
+  if (report.delivered > 0 || report.lastError !== undefined) {
+    appendEntry(
+      root,
+      makeEntry({
+        ts: new Date().toISOString(),
+        event: report.lastError === undefined ? "kb_ingested" : "kb_deferred",
+        outcome: `delivered:${report.delivered},remaining:${report.remaining}`,
+      }),
+    );
+  }
+  process.stdout.write(`pk-drain: delivered ${report.delivered}, remaining ${report.remaining}${report.lastError ? ` (${report.lastError})` : ""}\n`);
+} catch (err) {
+  process.stderr.write(`pk-drain: warning: ${err instanceof Error ? err.message : String(err)}\n`);
+}
+process.exitCode = 0;
diff --git a/.claude/hooks/src/scan-prometheus.mts b/.claude/hooks/src/scan-prometheus.mts
new file mode 100644
index 0000000..d98ab93
--- /dev/null
+++ b/.claude/hooks/src/scan-prometheus.mts
@@ -0,0 +1,62 @@
+// CLI: scan every text file under .prometheus/ (or the directory given as the
+// first argument) for PHI and secrets. Exits 1 when anything matches, printing
+// file:line:column and the rule id — never the matched text.
+import { existsSync, readdirSync, readFileSync, statSync } from "node:fs";
+import path from "node:path";
+import { fileURLToPath } from "node:url";
+
+import { parseAllowlist, scanText } from "./lib/scan.mjs";
+
+const MAX_BYTES = 5 * 1024 * 1024;
+
+function walk(dir: string, out: string[]): void {
+  for (const entry of readdirSync(dir, { withFileTypes: true })) {
+    const full = path.join(dir, entry.name);
+    if (entry.isDirectory()) walk(full, out);
+    else if (entry.isFile()) out.push(full);
+  }
+}
+
+function looksBinary(buf: Buffer): boolean {
+  return buf.subarray(0, 8000).includes(0);
+}
+
+// npm runs scripts from .claude/hooks/, so default to the repository that
+// contains this script (dist/ -> hooks/ -> .claude/ -> repo) unless Claude
+// Code supplied CLAUDE_PROJECT_DIR or a directory was passed explicitly.
+const repoRoot = process.env["CLAUDE_PROJECT_DIR"] ?? path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..", "..", "..");
+const root = process.argv[2] ?? path.join(repoRoot, ".prometheus");
+if (!existsSync(root)) {
+  console.log(`scan-prometheus: ${root} does not exist; nothing to scan`);
+  process.exit(0);
+}
+
+const allowlistFile = path.join(root, "scan-allowlist.json");
+const allowlist = parseAllowlist(existsSync(allowlistFile) ? readFileSync(allowlistFile, "utf8") : undefined);
+
+const files: string[] = [];
+walk(root, files);
+let hits = 0;
+let scanned = 0;
+for (const file of files.sort()) {
+  if (path.resolve(file) === path.resolve(allowlistFile)) continue;
+  if (statSync(file).size > MAX_BYTES) {
+    console.error(`scan-prometheus: ${path.relative(root, file)}: skipped (over 5 MB) — review manually`);
+    hits += 1;
+    continue;
+  }
+  const buf = readFileSync(file);
+  if (looksBinary(buf)) continue;
+  scanned += 1;
+  for (const m of scanText(buf.toString("utf8"), allowlist)) {
+    hits += 1;
+    console.error(`scan-prometheus: ${path.relative(root, file).split(path.sep).join("/")}:${m.line}:${m.column}: ${m.rule}`);
+  }
+}
+
+if (hits > 0) {
+  console.error(`scan-prometheus: ${hits} finding(s) in ${scanned} file(s); remove the content or add a reviewed literal to scan-allowlist.json`);
+  process.exitCode = 1;
+} else {
+  console.log(`scan-prometheus: clean (${scanned} file(s) scanned)`);
+}
