index 0000000..405da1b
--- /dev/null
+++ b/.claude/hooks/test/ledger.test.mjs
@@ -0,0 +1,120 @@
+import { test } from "node:test";
+import assert from "node:assert/strict";
+import { mkdtempSync, readFileSync, rmSync, mkdirSync, writeFileSync } from "node:fs";
+import { tmpdir } from "node:os";
+import path from "node:path";
+
+import {
+  LEDGER_FIELDS,
+  entryFromHook,
+  sanitizeId,
+  appendEntry,
+  ledgerPath,
+  parseLedger,
+  readKbdPosition,
+  sha256,
+  makeEntry,
+} from "../dist/lib/ledger.mjs";
+
+const NOW = new Date("2026-09-24T12:00:00.000Z");
+const SECRET_PROMPT = "Patient John Doe SSN 123-45-6789, token sk-abcdefghijklmnop";
+
+test("payload content fields never reach the entry", () => {
+  const input = {
+    hook_event_name: "PostToolUseFailure",
+    session_id: "0f8e1a2b-3c4d-5e6f-7a8b-9c0d1e2f3a4b",
+    tool_name: "Bash",
+    tool_input: { command: "psql postgres://admin:hunter2@db/fhir" },
+    tool_response: { stderr: SECRET_PROMPT },
+    prompt: SECRET_PROMPT,
+    error: SECRET_PROMPT,
+    transcript_path: "/Users/someone/.claude/x.jsonl",
+    cwd: "/Users/someone/repo",
+  };
+  const entry = entryFromHook(input, NOW, {});
+  const line = JSON.stringify(entry);
+  for (const needle of ["hunter2", "123-45-6789", "sk-abc", "John Doe", "transcript", "/Users/someone"]) {
+    assert.ok(!line.includes(needle), `leaked ${needle}`);
+  }
+  for (const key of Object.keys(entry)) assert.ok(LEDGER_FIELDS.includes(key), `unexpected field ${key}`);
+  assert.equal(entry.tool_name, "Bash");
+  assert.equal(entry.outcome, "failed");
+});
+
+test("prompts are recorded by length and hash only", () => {
+  const entry = entryFromHook({ hook_event_name: "UserPromptSubmit", prompt: SECRET_PROMPT }, NOW, {});
+  assert.equal(entry.prompt_chars, SECRET_PROMPT.length);
+  assert.equal(entry.prompt_sha256, sha256(SECRET_PROMPT));
+  assert.ok(!JSON.stringify(entry).includes("123-45-6789"));
+});
+
+test("subagent stop carries agent identity and KBD position", () => {
+  const entry = entryFromHook(
+    { hook_event_name: "SubagentStop", agent_type: "fhir-code-reviewer", agent_id: "a1b2c3", session_id: "s-1" },
+    NOW,
+    { phase: "agent-dev-team", change: "add-karpathy-agent-ledger" },
+  );
+  assert.deepEqual(entry, {
+    ts: "2026-09-24T12:00:00.000Z",
+    session_id: "s-1",
+    agent_type: "fhir-code-reviewer",
+    agent_id: "a1b2c3",
+    event: "SubagentStop",
+    outcome: "stopped",
+    kbd_phase: "agent-dev-team",
+    kbd_change: "add-karpathy-agent-ledger",
+  });
+});
+
+test("unrecorded events produce no entry", () => {
+  assert.equal(entryFromHook({ hook_event_name: "PreToolUse" }, NOW, {}), null);
+  assert.equal(entryFromHook({}, NOW, {}), null);
+});
+
+test("sanitizeId drops free text and oversize values", () => {
+  assert.equal(sanitizeId("fhir-tech-lead"), "fhir-tech-lead");
+  assert.equal(sanitizeId("mcp__plugin_x__tool"), "mcp__plugin_x__tool");
+  assert.equal(sanitizeId("my-plugin:reviewer"), "my-plugin:reviewer");
+  assert.equal(sanitizeId("John Doe"), undefined);
+  assert.equal(sanitizeId("a".repeat(129)), undefined);
+  assert.equal(sanitizeId(42), undefined);
+  assert.equal(sanitizeId("postgres://u:p@h"), undefined, "DSN");
+  assert.equal(sanitizeId("jane@example.org"), undefined, "email");
+  assert.equal(sanitizeId("123-45-6789"), undefined, "SSN-shaped id");
+  assert.equal(sanitizeId("0f8e1a2b-3c4d-5e6f-7a8b-9c0d1e2f3a4b"), "0f8e1a2b-3c4d-5e6f-7a8b-9c0d1e2f3a4b", "UUID");
+});
+
+test("makeEntry ignores non-allowlisted keys and requires ts/event", () => {
+  const entry = makeEntry({ ts: "t", event: "boundary_degraded", outcome: "no-python", detail: "x" });
+  assert.deepEqual(entry, { ts: "t", event: "boundary_degraded", outcome: "no-python" });
+  assert.throws(() => makeEntry({ event: "x" }));
+});
+
+test("appendEntry writes exactly one line per call and parseLedger skips corrupt lines", () => {
+  const root = mkdtempSync(path.join(tmpdir(), "ledger-"));
+  try {
+    appendEntry(root, makeEntry({ ts: "t1", event: "SubagentStart" }));
+    appendEntry(root, makeEntry({ ts: "t2", event: "SubagentStop" }));
+    const text = readFileSync(ledgerPath(root), "utf8");
+    assert.equal(text.split("\n").filter(Boolean).length, 2);
+    const parsed = parseLedger(`${text}{torn\n\n`);
+    assert.deepEqual(parsed.map((e) => e.ts), ["t1", "t2"]);
+  } finally {
+    rmSync(root, { recursive: true, force: true });
+  }
+});
+
+test("readKbdPosition prefers nextChange and tolerates a missing waypoint", () => {
+  const root = mkdtempSync(path.join(tmpdir(), "kbd-"));
+  try {
+    assert.deepEqual(readKbdPosition(root), {});
+    mkdirSync(path.join(root, ".kbd-orchestrator"));
+    writeFileSync(
+      path.join(root, ".kbd-orchestrator", "current-waypoint.json"),
+      JSON.stringify({ phase: "p1", change: "old", nextChange: "c2" }),
+    );
+    assert.deepEqual(readKbdPosition(root), { phase: "p1", change: "c2" });
+  } finally {
+    rmSync(root, { recursive: true, force: true });
+  }
+});
diff --git a/.claude/hooks/test/lib.test.mjs b/.claude/hooks/test/lib.test.mjs
new file mode 100644
index 0000000..8a29317
--- /dev/null
+++ b/.claude/hooks/test/lib.test.mjs
@@ -0,0 +1,102 @@
+// Tests run against the compiled dist/ so they exercise exactly what ships.
+import { test } from "node:test";
+import assert from "node:assert/strict";
+import { spawnSync } from "node:child_process";
+import { fileURLToPath, pathToFileURL } from "node:url";
+import path from "node:path";
+
+import { parseInput, renderResult, deny, feedback, context, warn, allow } from "../dist/lib/hook-io.mjs";
+import { toPosix, rel, projectDir } from "../dist/lib/paths.mjs";
+
+const here = path.dirname(fileURLToPath(import.meta.url));
+const hookIoUrl = pathToFileURL(path.join(here, "..", "dist", "lib", "hook-io.mjs")).href;
+
+/** Run a throwaway hook through runHook with the given stdin. */
+function runInlineHook(handlerSource, stdin) {
+  const script = `import { runHook, deny, allow } from ${JSON.stringify(hookIoUrl)};\n` +
+    `await runHook("t", ${handlerSource});`;
+  return spawnSync(process.execPath, ["--input-type=module", "-e", script], { input: stdin, encoding: "utf8" });
+}
+
+test("parseInput rejects empty, non-JSON, and non-object input", () => {
+  assert.equal(parseInput(""), null);
+  assert.equal(parseInput("not json"), null);
+  assert.equal(parseInput("[1,2]"), null);
+  assert.equal(parseInput("null"), null);
+  assert.deepEqual(parseInput('{"hook_event_name":"Stop"}'), { hook_event_name: "Stop" });
+});
+
+test("malformed stdin warns once and exits 0", () => {
+  const r = runInlineHook("() => deny('should not run')", "{{{");
+  assert.equal(r.status, 0);
+  assert.equal(r.stdout, "");
+  assert.match(r.stderr, /warning: ignoring malformed hook input/);
+  assert.equal(r.stderr.trim().split("\n").length, 1);
+});
+
+test("handler exceptions never block", () => {
+  const r = runInlineHook("() => { throw new Error('boom'); }", '{"hook_event_name":"Stop"}');
+  assert.equal(r.status, 0);
+  assert.match(r.stderr, /hook failed: boom/);
+});
+
+test("deny on PreToolUse emits a permission decision and exits 0", () => {
+  const out = renderResult(deny("generated file"), "PreToolUse");
+  assert.equal(out.exitCode, 0);
+  assert.deepEqual(JSON.parse(out.stdout), {
+    hookSpecificOutput: {
+      hookEventName: "PreToolUse",
+      permissionDecision: "deny",
+      permissionDecisionReason: "generated file",
+    },
+  });
+});
+
+test("deny on other events exits 2 with the reason on stderr", () => {
+  const out = renderResult(deny("stop here"), "UserPromptSubmit");
+  assert.equal(out.exitCode, 2);
+  assert.equal(out.stderr, "stop here\n");
+  const r = runInlineHook("() => deny('blocked')", '{"hook_event_name":"UserPromptSubmit"}');
+  assert.equal(r.status, 2);
+  assert.equal(r.stderr, "blocked\n");
+});
+
+test("feedback and context use hookSpecificOutput.additionalContext", () => {
+  for (const [result, event] of [[feedback("fix header"), "PostToolUse"], [context("phase: x"), "SessionStart"]]) {
+    const out = renderResult(result, event);
+    assert.equal(out.exitCode, 0);
+    const body = JSON.parse(out.stdout);
+    assert.equal(body.hookSpecificOutput.hookEventName, event);
+    assert.equal(typeof body.hookSpecificOutput.additionalContext, "string");
+  }
+});
+
+test("warn uses systemMessage and allow is silent", () => {
+  assert.deepEqual(JSON.parse(renderResult(warn("pk offline"), "Stop").stdout), { systemMessage: "pk offline" });
+  assert.deepEqual(renderResult(allow(), "Stop"), { stdout: "", stderr: "", exitCode: 0 });
+});
+
+test("toPosix normalizes Windows separators", () => {
+  assert.equal(toPosix("C:\\repo\\internal\\\\store\\x.go"), "C:/repo/internal/store/x.go");
+  assert.equal(toPosix("a/b"), "a/b");
+});
+
+test("rel resolves POSIX, Windows, and relative targets", () => {
+  assert.equal(rel("/repo", "/repo/internal/store/search.go"), "internal/store/search.go");
+  assert.equal(rel("C:\\repo", "C:\\repo\\.kbd-orchestrator\\current-waypoint.json"), ".kbd-orchestrator/current-waypoint.json");
+  assert.equal(rel("C:/Repo", "c:\\Repo\\a.go"), "a.go");
+  assert.equal(rel("/repo", "./internal/./db/../db/schema.sql"), "internal/db/schema.sql");
+  assert.equal(rel("/repo", "/repo"), "");
+});
+
+test("rel rejects paths outside the project", () => {
+  assert.equal(rel("/repo", "/other/x.go"), null);
+  assert.equal(rel("/repo", "/repository/x.go"), null);
+  assert.equal(rel("/repo", "../secrets.txt"), null);
+  assert.equal(rel("/repo", "a/../../b"), null);
+});
+
+test("projectDir prefers CLAUDE_PROJECT_DIR over cwd", () => {
+  assert.equal(projectDir({ CLAUDE_PROJECT_DIR: "C:\\work\\repo" }, "/ignored"), "C:/work/repo");
+  assert.equal(projectDir({}, "/tmp/x/"), "/tmp/x");
+});
