+      "description": "Node bridge to record-progress.py for task boundaries.",
+      "action": {
+        "type": "command",
+        "command": "node .claude/hooks/dist/karpathy-boundary.mjs --boundary task",
+        "timeout": 15,
+        "on_failure": "warn"
+      }
+    },
+    {
+      "id": "karpathy-boundary-node-change",
+      "event": "change:after",
+      "mode": "augment",
+      "description": "Node bridge to record-progress.py for change boundaries.",
+      "action": {
+        "type": "command",
+        "command": "node .claude/hooks/dist/karpathy-boundary.mjs --boundary change",
+        "timeout": 15,
+        "on_failure": "warn"
+      }
+    },
+    {
+      "id": "karpathy-boundary-node-phase",
+      "event": "phase:after",
+      "mode": "augment",
+      "description": "Node bridge to record-progress.py for phase boundaries.",
+      "action": {
+        "type": "command",
+        "command": "node .claude/hooks/dist/karpathy-boundary.mjs --boundary phase",
+        "timeout": 15,
+        "on_failure": "warn"
+      }
